// Why Code: transpose the key|value Settings tab into one object.
const rows = $input.all().map((i) => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key ?? '').trim();
  if (k) cfg[k] = r.value ?? '';
}
return [{ json: cfg }];

// Why Code: minute-window filter against 'now' + Luxon; native IF cannot do date deltas.
const cfg = $('Pivot Settings').first().json;
const facility = cfg.facilityName || 'the facility';
const tz = cfg.timezone || 'Africa/Lagos';
const base = String(cfg.publicBaseUrl || '').replace(/\/+$/, '');
const now = DateTime.now().setZone(tz);
const rows = $('Read Rota').all().map((i) => i.json);
const out = [];
for (const r of rows) {
  if (String(r.status).toUpperCase() !== 'PENDING') continue;
  if (String(r.reminder2hSent || '').trim()) continue;
  const start = DateTime.fromFormat(String(r.date) + ' ' + String(r.startTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  if (!start.isValid) continue;
  const mins = start.diff(now, 'minutes').minutes;
  if (mins <= 105 || mins > 135) continue;  // ~2h mark; cron runs every 15 min
  const link = base && r.confirmToken
    ? '\n\nConfirm in one tap: ' + base + '/webhook/confirm-shift?token=' + encodeURIComponent(r.confirmToken)
    : '';
  const reminderText = [
    'ShiftHub in 2 HOURS - ' + facility,
    '',
    'Hi ' + r.staffName + ', your shift starts in about 2 hours:',
    '- Shift:   ' + r.date + '  ' + r.startTime + ' to ' + r.endTime,
    '- Unit:    ' + r.ward + '  |  Role: ' + r.role,
    '- Shift ID: ' + r.shiftId,
    '',
    'Reply YES now to confirm - by Telegram, or by replying to this email.',
    'If you no longer can make it, phone your supervisor immediately.',
  ].join('\n') + link;
  out.push({ json: { ...r, reminderText,
    subject: '[ShiftHub] Starts in 2h - ' + r.ward + ' ' + r.startTime } });
}
return out;
